NUM_REG = {"wave": (470, 58, 620, 94), "stone": (525, 1505, 600, 1548), "unit": (660, 1505, 800, 1548)}
def _glyphs(im, box):
    x0, y0, x1, y1 = box; W = x1 - x0; H = y1 - y0
    px = im.crop(box).convert("RGB").load()
    wh = [[min(px[x, y]) > 215 for y in range(H)] for x in range(W)]
    cols = [sum(c) for c in wh]; out = []; x = 0
    while x < W:
        if cols[x] > 0:
            s0 = x
            while x < W and cols[x] > 0: x += 1
            ys = [y for xx in range(s0, x) for y in range(H) if wh[xx][y]]
            t, b = min(ys), max(ys) + 1
            if x - s0 >= 2 and b - t >= 20:
                g = Image.new("L", (x - s0, b - t))
                for xx in range(s0, x):
                    for y in range(t, b): g.putpixel((xx - s0, y - t), 255 if wh[xx][y] else 0)
                out.append(g)
        else: x += 1
    return out
def _read(im, key):
    s = ""
    for g in _glyphs(im, NUM_REG[key]):
        r = g.resize((10, 14)); v = [1 if q > 127 else 0 for q in (r.get_flattened_data() if hasattr(r, "get_flattened_data") else r.getdata())]
        d, k = min((sum(abs(a - b) for a, b in zip(v, t)), k) for k, t in DIGITS.items())
        if d > 25: return None
        s += k
    return s
def read_numbers(im):
    w = _read(im, "wave"); u = _read(im, "unit"); st = _read(im, "stone")
    wave = int(w.split("E")[-1]) if w and "E" in w and w.split("E")[-1].isdigit() else None
    unit = None
    if u and u.count("/") == 1:
        a, b = u.split("/")
        if a.isdigit() and b.isdigit() and int(a) <= int(b): unit = (int(a), int(b))
    stone = int(st) if st and st.isdigit() else None
    return wave, stone, unit

TPL = {k: bin(int.from_bytes(base64.b64decode(v), "big"))[2:].zfill(4800) for k, v in TPL_PACKED.items()}

