# 神話素材ノーマルの上限（同じユニットは1マス3体まで重なるので「マス数」で数える）
KEEP_CELLS = {"擲弾兵": 1, "水の精霊": 1, "山賊": 2}
# 神話素材 → 必要なレジェンド。対応レジェンドが盤面にいない時は素材も合成してよい（りゅうせい 11/24 01:44）
MAT_LEGENDS = {"木": ["虎の師父"], "擲弾兵": ["虎の師父", "ウォーマシン"], "ショックロボット": ["ウォーマシン"],
               "レンジャー": ["嵐の巨人"], "水の精霊": ["嵐の巨人"], "ハンター": ["保安官"], "サンドマン": ["保安官"]}  # 保安官はレジェンド（パネル金色で確認）
# ノーマルと確認できている素材（これ以外は売らない）
NORMAL_MAT = {"擲弾兵", "水の精霊"}
RARE = {"聖騎士", "悪魔の兵士", "サンドマン", "ショックロボット", "レンジャー"}  # ショックロボット・レンジャーはレア（りゅうせい 10:56）
# エピック（ハンター・木・ウルフ戦士・イーグル将軍は推定。合成後すぐ結果を確認する対象）
EPIC = {"ハンター", "木", "ウルフ戦士", "イーグル将軍", "電気ロボット"}  # ショックロボット・レンジャーはエピックではない（りゅうせい 10:55）
LEGEND_FOR = {"虎の師父": "バットマン", "ウォーマシン": "ロケッチュー", "嵐の巨人": "ウチ", "保安官": "ヘイリー"}
# レジェンドが出たら対応する神話素材を必要な分だけ残す（りゅうせい 02:46）
NEED = {"虎の師父": {"木": 1, "擲弾兵": 2}, "ウォーマシン": {"ショックロボット": 1, "擲弾兵": 1},
        "嵐の巨人": {"レンジャー": 1, "水の精霊": 1}, "保安官": {"ハンター": 1, "サンドマン": 1}}

def adb(*args, capture=False):
    r = subprocess.run([ADB, "-s", DEVICE] + list(args), capture_output=True)
    return r.stdout if capture else None

CELL_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "cells")
def save_panel(im):
    # 神話パネルの上部（名前・肖像）をそのまま保存。v0.43までは切り出し位置を間違えて説明文だけ保存していた
    try:
        d = os.path.join(CELL_DIR, "_神話パネル"); os.makedirs(d, exist_ok=True)
        if len(os.listdir(d)) >= 300: return
        im.crop((0, 150, 1080, 420)).save(os.path.join(d, "%d.png" % int(time.time()*1000)))
    except Exception as e:
        print("パネル保存失敗", e)

def save_cell(board, cx, cy, name):
    # タップ前の盤面からマスを切り出して cells/<名前>/ に保存（後で盤面だけで判定する分類器を作る）
    try:
        if board is None: return
        d = os.path.join(CELL_DIR, name); os.makedirs(d, exist_ok=True)
        if len(os.listdir(d)) >= 300: return
        board.crop((cx - 62, cy - 95, cx + 62, cy + 50)).save(os.path.join(d, "%d_%d_%d.png" % (int(time.time()*1000), cx, cy)))
    except Exception as e:
        print("cell保存失敗", e)

def is_empty_cell(board, cx, cy):
    # マスの中心が草の緑だけなら空き（りゅうせい 11:22 空白は押さない）。
    # 保存済みの盤面で確認: 空き 0〜0.16、ユニット有り 0.30以上 → 0.15未満を空きとする
    try:
        c = board.crop((cx - 45, cy - 40, cx + 45, cy + 40))
        px = c.get_flattened_data() if hasattr(c, "get_flattened_data") else c.getdata()
        n = sum(1 for r, g, b in px if not (g >= r - 10 and g > b + 40 and g > 80))
        return n / 7200 < 0.15
    except Exception:
        return False

def grab():
    try:
        im = Image.open(io.BytesIO(adb("exec-out", "screencap", "-p", capture=True))).convert("RGB")
        return im if im.size == (1080, 1920) else None
    except Exception:
        return None

def tap(x, y, n=1, gap=0.15):
    for _ in range(n):
        adb("shell", "input", "tap", str(int(x)), str(int(y)))
        time.sleep(gap)

def near(c, ref, tol=30):
    return all(abs(a - b) <= tol for a, b in zip(c, ref))

def count(im, box, fn, step=3):
    px = im.load(); x0, y0, x1, y1 = box
    return sum(1 for x in range(max(0, x0), min(1080, x1), step) for y in range(max(0, y0), min(1920, y1), step) if fn(px[x, y]))

def blob(im, cx, cy, fn, w=110, h=35, step=3):
    """(個数, 重心x) を返す"""
    px = im.load(); n = sx = 0
    for x in range(max(0, cx - w), min(1080, cx + w), step):
        for y in range(max(0, cy - h), min(1920, cy + h), step):
            if fn(px[x, y]): n += 1; sx += x
    return n, (sx / n if n else -999)

def has_btn(im, cx, cy, fn, minn):
    n, mx = blob(im, cx, cy, fn)
    return n >= minn and abs(mx - cx) < 30

def is_sell_red(p): r, g, b = p; return 150 <= r <= 200 and 25 <= g <= 60 and 55 <= b <= 95
def is_olive(p):   r, g, b = p; return 85 <= r <= 115 and 60 <= g <= 100 and b <= 25
def is_badge(p):   r, g, b = p; return r > 200 and g < 80 and b < 90
def is_yel(p):     r, g, b = p; return r > 235 and 200 < g < 250 and b < 80
def is_dred(p):    r, g, b = p; return 120 < r < 175 and g < 50 and b < 50

# ---- 画面判定 ----
def is_reward(im):   return near(im.getpixel((540, 1640)), (13, 190, 143))
def is_roulette(im): return near(im.getpixel((300, 1550)), (124, 189, 232)) and im.getpixel((790, 1550))[0] > 200
def is_enhance(im):
    if not near(im.getpixel((540, 1440)), (121, 78, 59), 20): return False
    return im.getpixel((1045, 1312))[0] > 245 or min(im.getpixel((1013, 1342))) > 240

def close_enhance():
    tap(1013, 1342); time.sleep(0.3)
def is_hunt(im):     return near(im.getpixel((120, 500)), (121, 78, 59), 20) and near(im.getpixel((540, 640)), (240, 227, 195), 20)
def hunt_ready(im):  return near(im.getpixel((540, 1170)), (233, 167, 22))
def is_match(im):
    def btn(p): r, g, b = p; return r > 195 and 140 < g < 215 and b < 70
    return btn(im.getpixel((440, 1600))) and btn(im.getpixel((640, 1600)))

def stars(im):
    px = im.load(); hits = []
    for y in range(300, 1400, 2):
        for x in range(40, 100, 2):
            if is_yel(px[x, y]) and (is_dred(px[x - 14, y]) or is_dred(px[x + 14, y])) and (is_dred(px[x, y - 16]) or is_dred(px[x, y + 16])):
                if not any(abs(x - a) < 40 and abs(y - b) < 40 for a, b in hits):
                    hits.append((x, y))
    return hits

NOT_BATMAN = {"ウチ": "", "ヘイリー": "", "ロケッチュー": ""}  # 手動強化ボタンが無い神話の名前（パネル名の2値画像）

def myth_name(im):
    b = panel_bits(im)
    for k, t in NOT_BATMAN.items():
        if sum(x != y for x, y in zip(b, t)) / 4800 < 0.03: return k
    return "バットマン"  # 名前が読めない神話はバットマン扱い

def panel_bits(im):
    c = im.crop((140, 304, 290, 336)).convert("L")
    return "".join("1" if v > 200 else "0" for v in (c.get_flattened_data() if hasattr(c, "get_flattened_data") else c.getdata()))

def is_merge_on(p):
    # 押せる合成ボタン=明るい黄色(233,167,22)・白文字。暗いオリーブ(96,69,9)は3体そろっていない＝押せない（02:55 画像で確認）
    r, g, b = p
    return abs(r - 233) < 16 and abs(g - 167) < 18 and b < 50

def is_mythic_panel(im):
    # 情報パネルの肖像の背景: 神話=オレンジ(198,115,46)、レジェンド=金(219,161,50)
    r, g, b = im.getpixel((130, 260)); p = im.getpixel((540, 250))
    return (r > 180 and 95 < g < 135 and b < 70
            and abs(p[0] - 205) < 14 and abs(p[1] - 186) < 14 and abs(p[2] - 160) < 14)

def read_name(im):
    c = im.crop((140, 304, 290, 336)).convert("L")
    bits = "".join("1" if v > 200 else "0" for v in (c.get_flattened_data() if hasattr(c, "get_flattened_data") else c.getdata()))
    best = min(((sum(a != b for a, b in zip(bits, t)) / 4800, k) for k, t in TPL.items()))
    return best[1] if best[0] < 0.03 else None

class Bot:
    def __init__(self):
        self.reset()
    def reset(self):
        self.start = None; self.free = self.burst = False
        self.mythics = 0; self.rewards = 0; self.enh = 0; self.mythic_cells = 0
        self.cells = {}; self.bandit_tries = 0; self.bandit_full = False; self.missing_mats = set()
        self.first_up = False; self.first_up_try = 0
        self.wave = None; self.stones = None; self.units = None; self.status = None
        self.last_scan = 0; self.board = set(); self.has_legend = False; self.star_fail = 0; self.stuff_tries = 0; self.collecting = False; self.ulb = {}

    # ボス報酬
    def reward(self, im):
        xs = [220, 540, 860]
        badge = [count(im, (x - 110, 580, x + 110, 670), is_badge) for x in xs]
        cols = [im.getpixel((x - 60, 680)) for x in xs]
        pick = None
        if max(badge) > 100: pick = badge.index(max(badge))
        if pick is None:
            for i, c in enumerate(cols):
                if near(c, (219, 161, 50)): pick = i; break
        if pick is None:
            for i, c in enumerate(cols):
                if near(c, (111, 55, 147)): pick = i; break
        if pick is None: pick = 2
        print("ボス報酬:", ["左", "中", "右"][pick])
        tap(xs[pick], 800); time.sleep(0.5); tap(540, 1345)
        self.rewards += 1; time.sleep(1.5)

    # エピックを合成したらすぐ同じマスを見て、何になったか確かめる（りゅうせい 10:54）
    def after_merge(self, cx, cy, name, seen):
        if name not in EPIC: return
        time.sleep(0.5); tap(cx, cy); time.sleep(0.4)
        im = grab()
        if im is None or not is_match(im): return
        if not has_btn(im, cx, cy + SELL_DY, is_sell_red, 60) and not is_mythic_panel(im):
            have = [k for k in LEGEND_FOR if k in self.board or k in seen]
            print("合成結果:", name, "→ マスが空＝既にいるレジェンドに重なった", ("(" + "・".join(have) + "のどれか)") if have else "(どれかは不明)")
            return
        got = read_name(im)
        print("合成結果:", name, "→", got or "名前読めず(神話パネル)" if is_mythic_panel(im) else got or "名前読めず")
        if got: seen.add(got)

    # 盤面スキャン
    def scan(self):
        seen = set(); acted = 0; cells = {}; where = {}; myth = 0; merged = 0; ulb = {}
        myth_names = set(); myth_where = {}
        top_name = {}  # 上の段の各列のユニット名（真ん中の押し直し確認用）
        board0 = grab()  # タップ前の盤面（盤面だけで見分けるための学習データ用）
        for cy in ROWS:
            for cx in COLS:
                if board0 is not None and is_empty_cell(board0, cx, cy):
                    continue  # 空きマスは押さない
                tap(cx, cy); time.sleep(0.35)
                im = grab()
                if im is not None and is_reward(im):
                    print("ボス報酬が出たのでスキャン中断"); self.reward(im); self.last_scan = time.time(); return acted
                if im is None or not is_match(im): continue
                
                # 下の段の神話を誤って拾うのはウチだけ（りゅうせい 11:15）。ウチの時だけ押し直す
                if is_mythic_panel(im) and cy != ROWS[-1] and myth_name(im) == "ウチ":
                    # 下の段の大きい神話（ウチなど）を拾っていることがあるので、マスの上寄りを押し直す（りゅうせい 09:32）
                    # 真ん中の段は -35 だと上すぎて上の段を拾う（りゅうせい 10:31）ので -15 にする
                    dy = 35 if cy == ROWS[0] else 15
                    tap(cx, cy - dy); time.sleep(0.35)
                    im_b = grab()
                    if im_b is not None and is_match(im_b) and not is_mythic_panel(im_b):
                        nb = read_name(im_b)
                        if not nb:
                            # 同じ神話をもう一度押すとパネルが閉じるだけ。これを「下の段の神話」と誤認して
                            # 神話を見落としていた（v0.36〜v0.52のバグ。移動・強化・オーバークロックが動かなかった原因の候補）
                            tap(cx, cy); time.sleep(0.35); im = grab() or im
                        elif cy != ROWS[0] and nb == top_name.get(cx):
                            print("押し直しが上の段を拾った→このマスは神話のまま", (cx, cy))
                        else:
                            print("下の段の神話を拾っていた→押し直し", (cx, cy)); im = im_b
                if is_mythic_panel(im):
                    myth += 1
                    # 神話をタップすると合成と同じ位置に強化ボタン。費用はコイン（りゅうせい 11/24 02:00, 02:03）。足りなければ押しても何も起きない
                    save_panel(im)
                    b = panel_bits(im)
                    known = [k for k, t in NOT_BATMAN.items() if sum(x != y for x, y in zip(b, t)) / 4800 < 0.03]
                    if known:
                        myth_names.add(known[0]); myth_where.setdefault(known[0], []).append((cx, cy))
                        save_cell(board0, cx, cy, "神話_" + known[0])  # 盤面だけで見分ける学習用（りゅうせい 12:09 神話がcellsに無い）
                        if known[0] == "ロケッチュー":
                            # ロケッチューは合成の位置にオーバークロック（りゅうせい 11/23 17:05, 11/24 11:01）
                            tap(cx, cy + MERGE_DY); time.sleep(0.5); print("ロケッチュー オーバークロック", (cx, cy)); acted += 1
                        else:
                            print("神話", known[0], "(強化ボタン無し)")
                        continue
                    myth_names.add("バットマン"); myth_where.setdefault("バットマン", []).append((cx, cy))
                    save_cell(board0, cx, cy, "神話_バットマン")  # 名前が読めない神話＝バットマン扱い
                    tap(cx, cy + MERGE_DY); time.sleep(0.5); print("神話を強化(コイン)", (cx, cy)); acted += 1
                    continue
                if not has_btn(im, cx, cy + SELL_DY, is_sell_red, 60):
                    continue  # 空きマス
                name = read_name(im)
                if not name: continue
                seen.add(name); where.setdefault(name, []).append((cx, cy))
                if cy == ROWS[0]: top_name[cx] = name
                save_cell(board0, cx, cy, name)
                can_merge = has_btn(im, cx, cy + MERGE_DY, is_merge_on, 120)
                cells[name] = cells.get(name, 0) + 1
                # 合成ボタンが押せる＝そのマスは3体。押せない＝1〜2体なので少なめに1体と数える（りゅうせい 03:12）
                ulb[name] = ulb.get(name, 0) + (3 if can_merge else 1)
                if name == "山賊" and can_merge: self.bandit_full = True
                over = name in KEEP_CELLS and cells[name] > KEEP_CELLS[name]
                # レジェンドが盤面にいない時はノーマル・レア・エピックを全部合成（りゅうせい 02:43）。電気ロボットは除く
                legends = [k for k in LEGEND_FOR if k in self.board or k in seen]
                no_legend = not legends
                need = {}
                for l in legends:
                    for m, c in NEED[l].items(): need[m] = need.get(m, 0) + c
                if name in need:
                    # 必要素材: 1マス目（最大3体）は残す。2マス目以降は合成、合成できなければ残す
                    if cells[name] == 1 or not can_merge:
                        continue
                    tap(cx, cy + MERGE_DY); time.sleep(0.6); self.after_merge(cx, cy, name, seen)
                    print("合成(素材の余り)", name); acted += 1; merged += 1
                    continue
                if name in RARE and self.full():
                    # 盤面いっぱい: 今いるレジェンドに使わないレアは売る（りゅうせい 10:39）。レジェンドがいなくても売る（10:40）
                    for _ in range(3):
                        tap(cx, cy + SELL_DY); time.sleep(0.4)
                        im2 = grab()
                        if im2 is None or not has_btn(im2, cx, cy + SELL_DY, is_sell_red, 60) or read_name(im2) != name:
                            break
                    print("販売(盤面いっぱい・不要レア)", name); acted += 1
                    continue
                if not no_legend and name in MAT_LEGENDS and name != "電気ロボット":
                    # レジェンド在り: 今いるレジェンドに不要な素材は合成、合成できなければ売却（りゅうせい 03:19）
                    if can_merge:
                        tap(cx, cy + MERGE_DY); time.sleep(0.6); self.after_merge(cx, cy, name, seen)
                        print("合成(不要素材)", name); acted += 1; merged += 1
                    elif name in NORMAL_MAT:
                        # 売るのはノーマル素材だけ。エピック・レアは売らない（りゅうせい 03:25, 02:14）
                        for _ in range(3):
                            tap(cx, cy + SELL_DY); time.sleep(0.4)
                            im2 = grab()
                            if im2 is None or not has_btn(im2, cx, cy + SELL_DY, is_sell_red, 60) or read_name(im2) != name:
                                break
                        print("販売(不要素材)", name); acted += 1
                    continue
                if no_legend and can_merge and name not in LEGEND_FOR and name not in NO_MERGE:
                    tap(cx, cy + MERGE_DY); time.sleep(0.6); self.after_merge(cx, cy, name, seen)
                    print("合成(レジェンド無し)", name); acted += 1; merged += 1
                    continue
                if over and name == "山賊" and (cx, cy) == (COLS[0], ROWS[-1]):
                    # 左下は山賊の定位置なので残し、先に見つけた別の山賊マスを売る（りゅうせい 11:11）
                    others = [q for q in where.get("山賊", []) if q != (cx, cy)]
                    if others:
                        x2, y2 = others[0]
                        tap(x2, y2); time.sleep(0.35); im2 = grab()
                        if im2 is not None and is_match(im2) and read_name(im2) == "山賊":
                            for _ in range(3):
                                tap(x2, y2 + SELL_DY); time.sleep(0.4)
                                im3 = grab()
                                if im3 is None or not has_btn(im3, x2, y2 + SELL_DY, is_sell_red, 60) or read_name(im3) != "山賊": break
                            where["山賊"].remove((x2, y2))
                            print("販売 山賊 (上限超え・左下は残す)", (x2, y2)); acted += 1
                    continue
                if name in SELL or over:
                    for _ in range(3):
                        tap(cx, cy + SELL_DY); time.sleep(0.4)
                        im2 = grab()
                        if im2 is None or not has_btn(im2, cx, cy + SELL_DY, is_sell_red, 60) or read_name(im2) != name:
                            break
                    print("販売", name, "(上限超え)" if over else ""); acted += 1
                elif (name in MERGE or name in MAT_LEGENDS) and can_merge:
                    if any(l in self.board for l in MAT_LEGENDS.get(name, [])): continue  # レジェンド在り→素材を残す
                    tap(cx, cy + MERGE_DY); time.sleep(0.6); self.after_merge(cx, cy, name, seen)
                    print("合成", name); acted += 1; merged += 1
        prev = self.board
        self.board = seen
        if prev:
            new = seen - prev
            if new: print("新しく盤面に出た:", "、".join(sorted(new)))
        if merged:
            # 合成で何ができたか確かめるため、次の周回ですぐ盤面を見直す（りゅうせい 03:03）
            self.recheck = True
        self.mythic_cells = myth  # 盤面で実際に見えた神話のマス数
        self.mythic_names = myth_names
        self.where = where
        self.cells = cells
        self.ulb = ulb  # ユニットごとの体数（少なめの見積もり）
        self.place(where, myth_where)
        self.has_legend = any(k in seen for k in LEGEND_FOR)
        self.last_scan = time.time() - (1000 if getattr(self, 'recheck', False) else 0)
        self.recheck = False
        return acted

    # 配置（りゅうせい 01:48, 11:04）: バットマン左上、電気ロボット上段左から2番目、山賊左下、
    # ウチは右下から上へ、ヘイリー・ロケッチューは真ん中の段の左から。動かす前に名前を確認し、1スキャン1体だけ
    def place(self, where, myth_where):
        right_up = [(COLS[-1], ROWS[2]), (COLS[-1], ROWS[1]), (COLS[-1], ROWS[0])]
        mid_left = [(c, ROWS[1]) for c in COLS]
        plan = [("バットマン", [(COLS[0], ROWS[0])], True), ("電気ロボット", [(COLS[1], ROWS[0])], False),
                ("山賊", [(COLS[0], ROWS[-1])], False), ("ウチ", right_up, True),
                ("ヘイリー", mid_left, True), ("ロケッチュー", mid_left, True)]
        if myth_where: print("神話の位置:", "、".join("%s%s" % (k, v) for k, v in myth_where.items()))
        taken = set()
        for name, slots, is_myth in plan:
            ps = list((myth_where if is_myth else where).get(name, []))
            if name in ("ヘイリー", "ロケッチュー"):
                slots = [g for g in slots if g not in taken]
            # 左から（ウチは下から）詰める: 欲しい場所は先頭から体数ぶんだけ。
            # v0.56までは列・段のどこかにいれば済みにしていたので動かなかった（りゅうせい 11:32）
            want = slots[:len(ps)]
            if name in ("ヘイリー", "ロケッチュー"): taken |= set(want)
            todo = [p for p in ps if p not in want]
            free = [g for g in want if g not in ps]
            if not todo or not free: continue
            print("配置しようとする:", name, todo[0], "→", free[0])
            (x, y), goal = todo[0], free[0]
            tap(x, y); time.sleep(0.35); im = grab()
            ok = im is not None and is_match(im) and ((is_myth and is_mythic_panel(im) and myth_name(im) == name) or (not is_myth and read_name(im) == name))
            if not ok:
                print("配置やめ:", name, "が", (x, y), "にいない"); continue
            adb("shell", "input", "swipe", str(x), str(y), str(goal[0]), str(goal[1]), "600")
            print("配置", name, (x, y), "→", goal); time.sleep(0.8)
            return  # 1回のスキャンで動かすのは1体だけ

    def pending_legend(self):
        return any(k in self.board for k in LEGEND_FOR)

    def enhance_phase(self):
        # 盤面に神話が1体もいなければ神話強化しない（りゅうせい 02:20）
        if self.mythic_cells < 1: return False
        return self.enh < 13 and (self.mythics >= 3 or self.rewards >= 5 or (self.wave or 0) > 50) and (self.stones is None or self.stones >= 2) and ((self.wave or 0) > 50 or not self.pending_legend())

    def full(self):
        return self.units is not None and self.units[0] >= self.units[1]

    def free_slots(self, n):
        if self.units is None: return n
        return max(0, min(n, self.units[1] - self.units[0]))

    def roulette(self):
        if self.stones is not None and self.stones < 1: return
        if self.full(): return  # 盤面が満杯ならルーレットも回さない（りゅうせい 02:17）
        tap(900, 1690); time.sleep(0.5)
        im = grab()
        if im is not None and is_roulette(im):
            # 神話素材のレアが足りない時はレアルーレット（りゅうせい 11:30）。左の青=レア(幸運石1・60%)
            lack_rare = sorted(m for m in getattr(self, "missing_mats", set()) if m in RARE) if self.collecting else []
            if lack_rare:
                print("レアルーレット（不足:", "・".join(lack_rare), "）")
                tap(296, 1550, n=8, gap=0.35); time.sleep(0.3)
            else:
                print("エピックルーレット")
                tap(540, 1550, n=8, gap=0.35); time.sleep(0.3)
            tap(956, 1324)

    def enhance(self):
        tap(540, 1850); time.sleep(0.5)
        im = grab()
        if im is not None and is_enhance(im):
            # 費用は幸運石 2,3,4,5…と1個ずつ増える（りゅうせい 02:24）。1回ずつ、2個は神話作成用に残す
            cost = self.enh + 2
            if self.stones is not None and self.stones < cost + 2:
                print("幸運石不足で強化見送り（費用", cost, "）"); close_enhance(); return
            tap(672, 1672); self.enh += 1
            print("神話強化 合計", self.enh)
            time.sleep(0.3); close_enhance()

    def step(self, im):
        if self.start is None:
            self.start = time.time(); print("試合を検出")
        t = time.time() - self.start
        w, st, u = read_numbers(im)
        if w is not None: self.wave = w
        if st is not None: self.stones = st
        if u is not None: self.units = u
        cur = (self.wave, self.stones, self.units)
        if cur != self.status:
            self.status = cur
            print("W%s 幸運石%s 盤面%s" % (self.wave if self.wave is not None else "?", self.stones if self.stones is not None else "?",
                  "%d/%d" % self.units if self.units else "?"))
        if self.wave is not None and self.wave >= 3 and t < 15 and not self.free:
            # 試合の途中から起動した時は、最初の召喚・強化・一気召喚をしない
            self.free = self.first_up = self.burst = True; print("途中から開始: 最初の召喚・強化・一気召喚はしない")
        if not self.free:
            tap(540, 1640); self.free = True; print("無料召喚")
        if not self.first_up:
            tap(540, 1850); time.sleep(0.6)
            im3 = grab()
            if im3 is not None and is_enhance(im3):
                tap(168, 1680); time.sleep(0.4); tap(416, 1680); time.sleep(0.4)
                print("最初の強化: ノーマル~レア 1回, エピック 1回")
                close_enhance(); time.sleep(0.4)
                self.first_up = True
            else:
                self.first_up_try += 1
                if self.first_up_try >= 2: self.first_up = True; print("最初の強化: 画面が開けずスキップ")
        if not self.burst and ((self.wave is not None and self.wave >= 3) or (self.wave is None and t > 40)):
            n = self.free_slots(25)
            print("一気召喚（W3: 山賊狙い）", n, "回"); tap(540, 1640, n=n, gap=0.12); self.burst = True
        # スキャンが90秒以上できていなければ最優先（他の処理で毎回returnして合成が止まるのを防ぐ）
        if self.burst and time.time() - self.last_scan > 90:
            print("スキャン遅延→優先実行"); self.scan(); return
        s = stars(im)
        if s and self.star_fail < 2:
            x, y = s[0]; tap(x + 45, y + 45)
            print("神話 即召喚", self.mythics); time.sleep(1.0)
            im4 = grab()
            self.star_fail = self.star_fail + 1 if (im4 is not None and stars(im4)) else 0
            if self.star_fail == 0: self.mythics += 1; self.last_scan = 0  # 召喚できたら盤面を見直す
            if self.star_fail >= 2: print("神話の即召喚が2回失敗→しばらく無視")
            return
        if not s: self.star_fail = 0
        tap(960, 440); time.sleep(0.5)
        im2 = grab()
        if im2 is not None and is_hunt(im2): return
        if self.burst and time.time() - self.last_scan > (25 if self.collecting else 45):
            self.scan()
            b = self.board
            # レジェンドができたら対応する素材を集める（りゅうせい 03:10）
            missing = {}
            for l in LEGEND_FOR:
                if l in b:
                    lack = ["%s(%d/%d)" % (m, self.ulb.get(m, 0), c) for m, c in NEED[l].items() if self.ulb.get(m, 0) < c]
                    if lack: missing[l] = lack
            self.collecting = bool(missing)
            self.missing_mats = {m for l in LEGEND_FOR if l in b for m, c in NEED[l].items() if self.ulb.get(m, 0) < c}
            if missing:
                print("素材集め:", " / ".join("%s→%s" % (l, "・".join(m)) for l, m in missing.items()))
                if self.full(): print("盤面いっぱいで素材召喚できない（次のスキャンで余りを合成して空ける）")
                elif self.stuff_tries < 12:
                    self.stuff_tries += 1
                    print("素材召喚", self.stuff_tries); tap(540, 1640, n=self.free_slots(5), gap=0.15)
                else: print("素材召喚12回で出ず→ルーレットだけで待つ")
            elif "ヘイリー" in getattr(self, "mythic_names", set()) and (self.wave or 0) >= 30:
                # ヘイリーは召喚で強化（りゅうせい 11/23 16:09）。W30以降だけ（11/24 11:02）。スキャン1回につき2体まで
                n = self.free_slots(2)
                if self.full():
                    # 盤面いっぱいなら売却して召喚（りゅうせい 11/24 11:02）。売るのはノーマル(野蛮人・弓兵)か、今いるレジェンドに使わないレア
                    need = set()
                    for l in LEGEND_FOR:
                        if l in self.board: need |= set(NEED[l])
                    cand = [(nm, p) for nm in list(SELL) + sorted(RARE - need) for p in getattr(self, "where", {}).get(nm, [])]
                    if cand:
                        nm, (x, y) = cand[0]
                        tap(x, y); time.sleep(0.35); im2 = grab()
                        if im2 is not None and is_match(im2) and read_name(im2) == nm:
                            for _ in range(3):
                                tap(x, y + SELL_DY); time.sleep(0.4)
                                im3 = grab()
                                if im3 is None or not has_btn(im3, x, y + SELL_DY, is_sell_red, 60) or read_name(im3) != nm: break
                            print("ヘイリー召喚のため売却", nm, (x, y)); n = 2
                        else: print("売却候補", nm, "がいなかった"); n = 0
                    else: print("盤面いっぱいで売れるユニットが無い→ヘイリー召喚なし"); n = 0
                if n:
                    print("ヘイリー強化の召喚"); tap(540, 1640, n=n, gap=0.15)
            elif not self.full() and self.cells.get("山賊", 0) == 0 and self.bandit_tries < 6:
                self.bandit_tries += 1
                print("山賊 追加召喚", self.bandit_tries, "（山賊マス", self.cells.get("山賊", 0), "）"); tap(540, 1640, n=self.free_slots(5), gap=0.15)
            return
        # 強化と神話作成(ルーレットで素材集め)を交互に。強化は幸運石を2個残す（りゅうせい 02:23）
        self.turn = getattr(self, "turn", 0) + 1
        # 盤面満杯だと素材集めは進まないので、その間は強化に幸運石を使う（shots8: W80で幸運石52個余り）
        if (not self.collecting or self.full()) and self.enhance_phase() and self.turn % 2 == 0 and (self.stones is None or self.stones >= self.enh + 4): self.enhance()
        else: self.roulette()
        time.sleep(1.0)

def main():
    print("開始。Ctrl+C で停止")
    bot = Bot(); idle = 0
    while True:
        im = grab()
        if im is None:
            print("画面が取れない。待機"); time.sleep(3); continue
        if is_reward(im): bot.reward(im); continue
        if is_roulette(im): tap(956, 1324); time.sleep(0.5); continue
        if is_enhance(im): close_enhance(); time.sleep(0.5); continue
        if is_hunt(im):
            if hunt_ready(im): tap(540, 1170); print("狩り")
            else: tap(950, 496)
            time.sleep(0.6); continue
        if not is_match(im):
            idle += 1
            if idle % 10 == 1: print("試合画面ではないので待機（ロビー・結果画面は押しません）")
            if idle > 20 and bot.start is not None:
                print("試合終了とみなしてリセット"); bot.reset()
            time.sleep(2); continue
        idle = 0
        bot.step(im)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("停止しました"); sys.exit(0)
